<script>
import {data,profile,updateData,toggleTask,notify} from '../lib/store.js';import {TASKS} from '../lib/catalog.js';import Icon from '../lib/components/Icon.svelte';
let {route='profile'}=$props();let taskFilter=$state('To do');let showAid=$state(false);let scholarshipFilter=$state('All opportunities');
const scholarships=[{id:'ceas',title:'Engineering scholarship resources',tag:'Engineering',text:'Explore scholarships and application information through CEAS.',url:'https://ceas.uc.edu/admissions/scholarships.html'},{id:'uc',title:'UC scholarship search',tag:'University-wide',text:'Start with official university scholarship information and eligibility.',url:'https://www.uc.edu/about/financial-aid/aid/scholarships.html'},{id:'international',title:'International student resources',tag:'International',text:'Find international student support and funding information through UC International.',url:'https://www.uc.edu/about/international.html'}];
let visibleTasks=$derived(TASKS.filter(t=>taskFilter==='All tasks'||(taskFilter==='Completed'?$data.completedTasks.includes(t.id):!$data.completedTasks.includes(t.id))));
function preference(name,value){updateData({...$data,preferences:{...$data.preferences,[name]:value}});notify('Preference saved for this demo profile.');}
function saveScholarship(id){updateData({...$data,savedScholarships:$data.savedScholarships.includes(id)?$data.savedScholarships.filter(x=>x!==id):[...$data.savedScholarships,id]});}
</script>
{#if route==='profile'}<div class="page-heading"><div><p class="eyebrow">Your space, your preferences</p><h1>My profile</h1><p>A clear overview of the student behind the schedule.</p></div><span class="badge neutral">Synthetic demo account</span></div><div class="progress-layout"><section class="panel padded"><div class="profile-title"><div class="avatar large">{$profile.initials}</div><div><h2>{$profile.name}</h2><p class="muted">{$profile.major} · {$profile.degree}</p></div></div><dl class="account-details"><div><dt>Student ID</dt><dd>{$profile.studentId}</dd></div><div><dt>Academic level</dt><dd>{$profile.year}</dd></div><div><dt>College</dt><dd>{$profile.college}</dd></div><div><dt>Target graduation</dt><dd>{$profile.graduation}</dd></div><div><dt>Data source</dt><dd>Synthetic student plan and transcript</dd></div></dl><p class="fine-print">Personal details are fixed demo data. No real student account or university authentication is connected.</p></section><section class="panel padded"><h2>Make it work for you</h2><label class="task-check"><input type="checkbox" checked={$data.preferences.reminders} onchange={e=>preference('reminders',e.currentTarget.checked)}/><span><strong>Show task reminders</strong><small>Display the task count in the workspace navigation.</small></span></label><label class="task-check"><input type="checkbox" checked={$data.preferences.compactSchedule} onchange={e=>preference('compactSchedule',e.currentTarget.checked)}/><span><strong>Compact schedule display</strong><small>Reduce spacing in your weekly schedule.</small></span></label><div class="notice"><Icon name="info"/><p>Preferences stay in this browser. No emails, notifications, or university records are changed.</p></div></section></div>
{:else if route==='tasks'}<div class="page-heading"><div><p class="eyebrow">One next step at a time</p><h1>Tasks & reminders</h1><p>Small actions that help keep your semester moving.</p></div><span class="term-pill">{$data.completedTasks.length} of {TASKS.length} complete</span></div><div class="category-chips">{#each ['To do','Completed','All tasks'] as f}<button class:active={taskFilter===f} aria-pressed={taskFilter===f} onclick={()=>taskFilter=f}>{f}</button>{/each}</div>{#each visibleTasks as t}<article class="panel task-card"><label class="task-check"><input type="checkbox" checked={$data.completedTasks.includes(t.id)} onchange={()=>toggleTask(t.id)}/><span><strong>{t.title}</strong><small>{t.description}</small><span class="badge neutral">{t.due}</span></span></label><a class="button secondary" href={t.href}>{t.action}<Icon name="arrow" size={16}/></a></article>{/each}{#if !visibleTasks.length}<div class="empty-state panel"><span class="success-seal"><Icon name="check" size={30}/></span><h2>{taskFilter==='Completed'?'Your progress will appear here.':'A little breathing room.'}</h2><p>{taskFilter==='Completed'?'Check off a task once you’ve completed it.':'You’re caught up with the demo task list.'}</p></div>{/if}<p class="fine-print">This is a personal demo checklist. It does not clear official service indicators or university holds.</p>
{:else if route==='finances'}<div class="page-heading"><div><p class="eyebrow">A clearer financial picture</p><h1>Student finances</h1><p>An illustrative overview, with the right next steps close by.</p></div><span class="badge warning">Demo amounts only</span></div><div class="metrics-grid three"><div class="metric panel"><span>Illustrative balance</span><strong>$0<small>.00</small></strong><p>No real billing account connected</p></div><div class="metric panel"><span>Account status</span><strong class="smaller">Demo only</strong><p>Verify actual balances in Catalyst</p></div><div class="metric panel"><span>Next step</span><strong class="smaller">Review aid</strong><p>Check official eligibility & deadlines</p></div></div><div class="bottom-grid"><section class="panel padded"><h2>Financial-aid checklist</h2><p class="muted spaced">Use the official financial-aid website to review your requirements, award details, and questions.</p><button class="button secondary spaced" aria-expanded={showAid} onclick={()=>showAid=!showAid}>{showAid?'Hide':'View'} planning checklist<Icon name="down" size={16}/></button>{#if showAid}<ul class="plain-list"><li>Review your official award information.</li><li>Confirm any outstanding documents.</li><li>Ask how schedule changes could affect your aid.</li><li>Verify payment deadlines directly with UC.</li></ul>{/if}<a class="button primary spaced" href="https://www.uc.edu/about/financial-aid.html" target="_blank" rel="noreferrer">Open UC Financial Aid<Icon name="external" size={16}/></a></section><section class="advisor-panel"><Icon name="star" size={28}/><h2>Find support for your next chapter.</h2><p>Browse official scholarship resources and save useful links to revisit.</p><a class="button secondary" href="#/scholarships">Explore scholarships<Icon name="arrow" size={16}/></a></section></div>
{:else if route==='scholarships'}<div class="page-heading"><div><p class="eyebrow">Make possibilities easier to find</p><h1>Scholarship resources</h1><p>Start with official information. Save a useful place to come back to.</p></div><span class="term-pill">{$data.savedScholarships.length} saved</span></div><div class="category-chips">{#each ['All opportunities','Saved resources'] as f}<button class:active={scholarshipFilter===f} aria-pressed={scholarshipFilter===f} onclick={()=>scholarshipFilter=f}>{f}</button>{/each}</div><div class="services-grid">{#each scholarships.filter(s=>scholarshipFilter==='All opportunities'||$data.savedScholarships.includes(s.id)) as s}<article class="service-card panel"><span class="tile-icon"><Icon name="star" size={24}/></span><span class="eyebrow">{s.tag}</span><h2>{s.title}</h2><p>{s.text}</p><div class="button-row"><a class="button secondary" href={s.url} target="_blank" rel="noreferrer">Visit resource<Icon name="external" size={15}/></a><button class="icon-button" class:saved={$data.savedScholarships.includes(s.id)} aria-label={`${$data.savedScholarships.includes(s.id)?'Unsave':'Save'} ${s.title}`} aria-pressed={$data.savedScholarships.includes(s.id)} onclick={()=>saveScholarship(s.id)}><Icon name="star"/></button></div></article>{/each}</div>{#if scholarshipFilter==='Saved resources'&&!$data.savedScholarships.length}<div class="empty-state panel"><h2>Keep a useful resource close.</h2><p>Use the star on a resource card to save it here.</p></div>{/if}<p class="fine-print">These are resource links, not scholarship matches or eligibility determinations. Applications take place on official websites.</p>{/if}
